import { defaultAccent, deriveAccent, type AccentTokens } from "./accent.ts";
import { neutral, overlay, type NeutralTokens, type Theme } from "./neutral.ts";
import {
  atmosphere,
  duration,
  easing,
  elevation,
  fontFamily,
  fontSize,
  iconSize,
  radius,
  shell,
} from "./scale.ts";
import { semantic, tones } from "./semantic.ts";

/**
 * Renders the tokens as CSS custom properties (`tokens.css`) and the Tailwind CSS v4 theme that
 * maps utilities onto them (`tailwind.css`). Both files are generated by
 * `pnpm --filter @madeora/design-tokens generate` and checked for drift by its tests.
 */

const HEADER =
  "/* Generated from packages/design-tokens/src by `pnpm --filter @madeora/design-tokens generate`. Do not edit. */";

function kebab(name: string): string {
  return name.replace(/[A-Z]/g, (letter) => `-${letter.toLowerCase()}`);
}

const neutralKeys = Object.keys(neutral.light) as (keyof NeutralTokens)[];
const accentKeys: readonly (keyof AccentTokens)[] = [
  "accent",
  "accentHover",
  "accentPressed",
  "onAccent",
  "accentSubtle",
  "accentFg",
  "focusRing",
  "accentEdge",
];

/** Colour names as Tailwind sees them (`bg-<name>`, `text-<name>`, `border-<name>`). */
export function colourNames(): string[] {
  return [
    ...neutralKeys.map(kebab),
    ...accentKeys.map((key) => (key === "focusRing" ? "focus" : kebab(key))),
    ...tones.flatMap((tone) => [tone, `${tone}-subtle`, `${tone}-solid`, `on-${tone}`]),
    "overlay",
  ];
}

/** The theme-dependent custom properties, as `[name, value]` pairs. */
export function themeVariables(theme: Theme): [string, string][] {
  const accent = deriveAccent(defaultAccent[theme], theme);
  const vars: [string, string][] = [];
  for (const key of neutralKeys) vars.push([`--md-color-${kebab(key)}`, neutral[theme][key]]);
  for (const key of accentKeys) {
    vars.push([`--md-color-${key === "focusRing" ? "focus" : kebab(key)}`, accent[key]]);
  }
  for (const tone of tones) {
    const t = semantic[theme][tone];
    vars.push([`--md-color-${tone}`, t.fg]);
    vars.push([`--md-color-${tone}-subtle`, t.subtle]);
    vars.push([`--md-color-${tone}-solid`, t.solid]);
    vars.push([`--md-color-on-${tone}`, t.onSolid]);
  }
  vars.push(["--md-color-overlay", overlay[theme]]);
  vars.push(["--md-shadow-card", elevation[theme].card]);
  vars.push(["--md-shadow-overlay", elevation[theme].overlay]);
  vars.push(["--md-atmosphere-cool", atmosphere[theme].cool]);
  vars.push(["--md-atmosphere-accent-strength", atmosphere[theme].accentStrength]);
  vars.push(["--md-atmosphere-cool-strength", atmosphere[theme].coolStrength]);
  // Declared in every theme block, because custom properties resolve where they are declared:
  // an element that forces a theme gets a background built from its own values.
  vars.push([
    "--md-atmosphere",
    "radial-gradient(60rem 36rem at 12% -12%, color-mix(in srgb, var(--md-color-accent) var(--md-atmosphere-accent-strength), transparent), transparent 70%), " +
      "radial-gradient(52rem 32rem at 92% -8%, color-mix(in srgb, var(--md-atmosphere-cool) var(--md-atmosphere-cool-strength), transparent), transparent 70%)",
  ]);
  return vars;
}

function staticVariables(): [string, string][] {
  const vars: [string, string][] = [["--md-font-sans", fontFamily.sans]];
  for (const [name, value] of Object.entries(fontSize)) {
    vars.push([`--md-text-${name}`, value.size]);
    vars.push([`--md-text-${name}-line-height`, value.lineHeight]);
  }
  for (const [name, value] of Object.entries(radius)) vars.push([`--md-radius-${name}`, value]);
  for (const [name, value] of Object.entries(shell)) vars.push([`--md-shell-${name}`, value]);
  for (const [name, value] of Object.entries(iconSize))
    vars.push([`--md-icon-${name}`, `${String(value)}px`]);
  for (const [name, value] of Object.entries(duration)) vars.push([`--md-duration-${name}`, value]);
  for (const [name, value] of Object.entries(easing)) vars.push([`--md-ease-${name}`, value]);
  return vars;
}

function block(selector: string, vars: [string, string][], indent = ""): string {
  const body = vars.map(([name, value]) => `${indent}  ${name}: ${value};`).join("\n");
  return `${indent}${selector} {\n${body}\n${indent}}`;
}

export function renderTokensCss(): string {
  const light: [string, string][] = [["color-scheme", "light"], ...themeVariables("light")];
  const dark: [string, string][] = [["color-scheme", "dark"], ...themeVariables("dark")];
  const zeroDurations = Object.keys(duration).map((name): [string, string] => [
    `--md-duration-${name}`,
    "0ms",
  ]);

  return [
    HEADER,
    "",
    "/* Light is the default. `data-theme` on an element forces a theme for it and its children. */",
    block(":root", staticVariables()),
    "",
    block(':root,\n[data-theme="light"]', light),
    "",
    "/* With no explicit choice, follow the operating system. */",
    "@media (prefers-color-scheme: dark) {",
    block(':root:not([data-theme="light"])', dark, "  "),
    "}",
    "",
    block('[data-theme="dark"]', dark),
    "",
    "/* Reduced motion: every transition and animation built on the duration tokens stops moving. */",
    "@media (prefers-reduced-motion: reduce) {",
    block(":root", zeroDurations, "  "),
    "}",
    "",
  ].join("\n");
}

export function renderTailwindCss(): string {
  const colours = colourNames().map((name): [string, string] => [
    `--color-${name}`,
    `var(--md-color-${name})`,
  ]);
  const text = Object.keys(fontSize).flatMap((name): [string, string][] => [
    [`--text-${name}`, `var(--md-text-${name})`],
    [`--text-${name}--line-height`, `var(--md-text-${name}-line-height)`],
  ]);
  const radii = Object.keys(radius).map((name): [string, string] => [
    `--radius-${name}`,
    `var(--md-radius-${name})`,
  ]);
  const easings = Object.keys(easing).map((name): [string, string] => [
    `--ease-${name}`,
    `var(--md-ease-${name})`,
  ]);

  return [
    HEADER,
    "",
    "/* Tailwind's default colour palette is removed, so only Madeora tokens exist as colour utilities. */",
    block("@theme", [["--color-*", "initial"]]),
    "",
    block("@theme inline", [
      ...colours,
      ["--font-sans", "var(--md-font-sans)"],
      ...text,
      ...radii,
      ["--shadow-card", "var(--md-shadow-card)"],
      ["--shadow-overlay", "var(--md-shadow-overlay)"],
      ...easings,
    ]),
    "",
  ].join("\n");
}
